import {CLIP_BEATS,clipStory} from './featured-clip.js';
const ptTitles=['O duelo','A condução','O chute','A reação do goleiro','Depois do chute'];
const ptObservations=['Um atacante de verde-lima encara um defensor de azul-claro com a bola nos pés.','O atacante de verde avança em direção à área com um defensor por perto.','O atacante executa um chute perto da área do gol.','O goleiro de laranja salta com as duas luvas levantadas em direção à bola.','O atacante levanta as mãos em direção à cabeça enquanto o goleiro desce.'];
export const labels={en:{analyst:'Tactical analyst',reviewer:'Evidence reviewer',presenter:'Match presenter',fan:'For the fan',beginner:'New to football',math:'Show the math',player:'Follow No. 8'},es:{analyst:'Analista táctico',reviewer:'Revisor de evidencia',presenter:'Presentador',fan:'Para el aficionado',beginner:'Nuevo en el fútbol',math:'Ver las matemáticas',player:'Sigue al 8'},pt:{analyst:'Analista tático',reviewer:'Revisor de evidências',presenter:'Apresentador',fan:'Para o torcedor',beginner:'Novo no futebol',math:'Ver a matemática',player:'Siga o camisa 8'}};
export function observedBeats(time,language='en'){return CLIP_BEATS.filter(b=>b.at<=time).map((b,i)=>({id:b.id,at:b.at,title:language==='pt'?ptTitles[i]:b.title[language==='es'?1:0],observation:language==='pt'?ptObservations[i]:b.observation[language==='es'?1:0]}));}
export function videoLesson(time,mode='fan',language='en'){
 const t=Math.max(0,Math.min(8,Number(time)||0)),seen=observedBeats(t,language),beat=seen.at(-1),i=seen.length-1,es=language==='es',pt=language==='pt';
 const before={title:es?'Cada toque tiene una historia.':pt?'Cada toque tem uma história.':'Every touch has a story.',body:es?'Reproduce el vídeo. La explicación sigue la acción y el panel de IA comenta al final.':pt?'Reproduza o vídeo. A explicação acompanha a jogada e o painel de IA comenta no final.':'Play the film. Your explanation follows the action, and the AI desk joins you after the final frame.'};
 if(!beat)return {...before,evidence:seen,math:null};
 let story=clipStory(t,{fan:'casual',analyst:'analyst',player:'player'}[mode]||'casual',language);
 let title=pt?ptTitles[i]:story.title,body=pt?ptObservations[i]:story.body;
 if(mode==='beginner'){
  const copy={en:[['A duel means one against one.','The player with the ball is the attacker. The defender is trying to stop him. Watch how the attacker chooses his next touch.'],['A carry means moving with the ball.','The attacker runs with the ball toward the goal. The nearby defender makes that harder.'],['A shot is an attempt to score.','The attacker kicks toward goal. A shot is an attempt, so it does not automatically mean a goal.'],['The goalkeeper protects the goal.','The player in orange raises his gloves toward the ball. We can see the reaction, but cannot confirm what happened to the ball.'],['A reaction is not a result.','The attacker raises his hands. That gesture alone cannot tell us whether the shot was saved, missed or scored.']],es:[['Un duelo es uno contra uno.','El atacante tiene el balón y el defensor intenta detenerlo. Mira cómo elige su siguiente toque.'],['Conducir es moverse con el balón.','El atacante avanza hacia la portería. El defensor cercano dificulta su camino.'],['Un disparo es un intento de marcar.','El atacante chuta hacia la portería. Un disparo no significa automáticamente un gol.'],['El portero protege la portería.','El jugador de naranja levanta los guantes. Vemos la reacción, pero no podemos confirmar el resultado.'],['Una reacción no es el resultado.','El atacante levanta las manos. El gesto no confirma una parada, un fallo ni un gol.']],pt:[['Um duelo é um contra um.','O atacante está com a bola e o defensor tenta pará-lo. Observe como ele escolhe o próximo toque.'],['Conduzir é avançar com a bola.','O atacante corre em direção ao gol. O defensor próximo dificulta o caminho.'],['Um chute é uma tentativa de marcar.','O atacante chuta em direção ao gol. Isso não significa automaticamente um gol.'],['O goleiro protege o gol.','O jogador de laranja levanta as luvas. Vemos a reação, mas não podemos confirmar o resultado.'],['Uma reação não é o resultado.','O atacante levanta as mãos. O gesto não confirma defesa, erro ou gol.']]};[title,body]=copy[language][i];
 }else if(pt&&mode==='analyst'){body+=' A câmera não permite medir velocidade nem estabelecer a organização defensiva. O resultado do chute não foi confirmado.';}else if(pt&&mode==='player'){title='Siga o atacante de verde.';body+=' O nome do jogador e sua emoção não são conhecidos.';}
 let math=null;
 if(mode==='math'){
  title=es?'Lo que el reloj puede demostrar.':pt?'O que o relógio pode mostrar.':'What the clock can actually tell us.';
  body=es?'Los tiempos describen el vídeo, no mediciones físicas. Calcular velocidad requiere distancia calibrada y tiempo; aquí no conocemos la distancia.':pt?'Os tempos descrevem o vídeo, não medidas físicas. Calcular velocidade exige distância calibrada e tempo; aqui a distância não é conhecida.':'Video time is measurable. Physical speed needs calibrated distance and elapsed time; this camera view gives us no reliable distance.';
  const interval=t>=4.5?1.2:null;
  math=(es?`Vídeo visto: ${t.toFixed(1)} ÷ 8 × 100 ≈ ${Math.round(t/8*100)}%`:pt?`Vídeo visto: ${t.toFixed(1)} ÷ 8 × 100 ≈ ${Math.round(t/8*100)}%`:`Clip progress: ${t.toFixed(1)} ÷ 8 × 100 ≈ ${Math.round(t/8*100)}%`)+(interval!==null?(es?'\nDisparo → reacción visible: 4.50 − 3.30 ≈ 1.20 s\nIntervalo entre anotaciones; no tiempo de reacción medido.':pt?'\nChute → reação visível: 4.50 − 3.30 ≈ 1.20 s\nIntervalo entre anotações; não é tempo de reação medido.':'\nStrike → visible response: 4.50 − 3.30 ≈ 1.20 s\nAnnotation interval; not a measured reaction time.'):'')+(es?'\nVelocidad = distancia ÷ tiempo → distancia desconocida':pt?'\nVelocidade = distância ÷ tempo → distância desconhecida':'\nSpeed = distance ÷ time → distance unknown');
 }
 return {title,body,evidence:seen,math,activeId:beat.id};
}
export function discussionKey(language,mode){return `${language}:${mode}`;}
export function canRevealDiscussion(time,previouslyUnlocked=false){return previouslyUnlocked||time>=7.95;}
